def _encode_context_messages(messages):
    """A deterministic encoder whose token count is not a character count."""

    rendered = json.dumps(
        messages,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return tuple(
        (sum(rendered[index : index + 8]) % 251) + 1
        for index in range(0, len(rendered), 8)
    )


def _context_policy(**changes):
    values = {
        "max_tokens": 800,
        "reserve_tokens": 630,
        "summary_max_tokens": 64,
        "max_tool_result_tokens": 48,
        "min_recent_turns": 1,
    }
    values.update(changes)
    return ContextPolicy(**values)


def _append_context_turn(session, number, *, result_words=80):
    response = json.dumps({"tool": "list_files", "path": f"part-{number}"})
    session.append("assistant_message", content=response)
    call = session.append(
        "tool_call",
        tool="list_files",
        arguments={"path": f"part-{number}"},
    )
    session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="list_files",
        is_error=False,
        content=(f"result-{number} " * result_words).strip(),
    )


def _summary_payload(**changes):
    values = {
        "goal": "fix empty configuration parsing",
        "constraints": ["keep the public schema"],
        "facts": ["parse_value is in src/config.py"],
        "changed_files": ["src/config.py"],
        "validation": ["test_empty_value still fails"],
        "failed_approaches": ["changing the default broke another test"],
        "next_step": "inspect normalization",
    }
    values.update(changes)
    return json.loads(json.dumps(asdict(WorkingSummary(**values))))


def _events_of_type(session, event_type):
    return [event for event in session.events if event.type == event_type]


