def test_task_4_working_summary_has_an_explicit_stable_schema():
    summary = _summary_payload()
    value = WorkingSummary(
        goal="goal",
        constraints=["constraint"],
        facts=[],
        changed_files=[],
        validation=[],
        failed_approaches=[],
        next_step="continue",
    )

    assert list(summary) == [
        "goal",
        "constraints",
        "facts",
        "changed_files",
        "validation",
        "failed_approaches",
        "next_step",
    ]
    assert isinstance(summary["goal"], str)
    assert isinstance(summary["next_step"], str)
    assert all(
        isinstance(summary[field], list)
        for field in (
            "constraints",
            "facts",
            "changed_files",
            "validation",
            "failed_approaches",
        )
    )
    assert value.constraints == ("constraint",)
    with pytest.raises(AttributeError):
        value.constraints.append("mutable")


def test_task_4_under_threshold_uses_the_exact_encoder_without_summarizing(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="inspect one small file", kind="task")
    encoded_messages = []

    def encode(messages):
        encoded_messages.append([dict(message) for message in messages])
        return _encode_context_messages(messages)

    def unexpected_summary(_messages):
        raise AssertionError("an under-budget context must not be summarized")

    original_events = session.events
    manager = ContextManager(
        encode,
        policy=_context_policy(max_tokens=512, reserve_tokens=64),
    )

    window = manager.prepare(session, "system", summarize=unexpected_summary)

    assert encoded_messages[-1] == list(window.messages)
    assert tuple(window.token_ids) == _encode_context_messages(window.messages)
    assert len(window.token_ids) < 512 - 64
    assert window.followed_compaction is False
    assert window.compaction_event_id is None
    assert window.visible_tool_result_bytes == 0
    assert session.events == original_events


def test_task_4_bounds_visible_tool_results_without_mutating_the_trace(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="inspect generated output", kind="task")
    original_result = "private-output " * 400
    response = '{"tool":"read_file","path":"output.txt"}'
    session.append("assistant_message", content=response)
    call = session.append(
        "tool_call",
        tool="read_file",
        arguments={"path": "output.txt"},
    )
    result = session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="read_file",
        is_error=False,
        content=original_result,
    )
    original_events = session.events
    manager = ContextManager(
        _encode_context_messages,
        policy=_context_policy(
            max_tokens=512,
            reserve_tokens=64,
            max_tool_result_tokens=12,
        ),
    )

    window = manager.prepare(session, "system")

    visible_results = [
        message["content"].removeprefix("Tool result:\n")
        for message in window.messages
        if message["content"].startswith("Tool result:\n")
    ]
    assert len(visible_results) == 1
    assert "omitted" in visible_results[0].lower()
    assert len(visible_results[0]) < len(original_result)
    assert window.visible_tool_result_bytes == len(visible_results[0].encode("utf-8"))
    assert window.followed_compaction is False
    assert session.events == original_events
    assert session.events[-1].id == result.id
    assert session.events[-1].data["content"] == original_result


