def test_task_4_repeated_compaction_advances_without_resummarizing_same_events(
    tmp_path,
):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="finish the migration", kind="task")
    for number in range(6):
        _append_context_turn(session, number)
    calls = 0

    def summarize(_messages):
        nonlocal calls
        calls += 1
        return json.dumps(
            _summary_payload(
                facts=[f"completed compaction {calls}"],
                next_step=f"continue after compaction {calls}",
            )
        )

    manager = ContextManager(_encode_context_messages, policy=_context_policy())

    first = manager.prepare(session, "system", summarize=summarize)
    manager.prepare(session, "system", summarize=summarize)
    assert calls == 1
    assert len(_events_of_type(session, "compaction")) == 1
    for number in range(6, 12):
        _append_context_turn(session, number)
    second = manager.prepare(session, "system", summarize=summarize)

    compactions = _events_of_type(session, "compaction")
    assert calls == len(compactions) == 2
    assert first.compaction_event_id == compactions[0].id
    assert second.compaction_event_id == compactions[1].id
    assert (
        compactions[0].data["covered_through_event_id"]
        != compactions[1].data["covered_through_event_id"]
    )
    assert "completed compaction 2" in "\n".join(
        message["content"] for message in second.messages
    )


