def test_task_4_deterministic_summary_keeps_structured_change_facts(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="repair configuration parsing", kind="task")
    edit_response = json.dumps(
        {
            "tool": "edit_file",
            "path": "src/config.py",
            "old": "return raw",
            "new": "return normalize(raw)",
        }
    )
    session.append("assistant_message", content=edit_response)
    edit_call = session.append(
        "tool_call",
        tool="edit_file",
        arguments={
            "path": "src/config.py",
            "old": "return raw",
            "new": "return normalize(raw)",
        },
    )
    session.append(
        "tool_result",
        tool_call_id=edit_call.id,
        tool="edit_file",
        is_error=False,
        content="wrote src/config.py",
    )
    command_response = json.dumps(
        {"tool": "run_command", "argv": ["safe-test", "config"]}
    )
    session.append("assistant_message", content=command_response)
    command_call = session.append(
        "tool_call",
        tool="run_command",
        arguments={"argv": ["safe-test", "config"]},
    )
    session.append(
        "tool_result",
        tool_call_id=command_call.id,
        tool="run_command",
        is_error=False,
        content="exit code: 7\ntest_empty_value failed",
    )
    for number in range(6):
        _append_context_turn(session, number)
    manager = ContextManager(_encode_context_messages, policy=_context_policy())

    manager.prepare(session, "system", summarize=lambda _messages: "invalid")

    summary = _events_of_type(session, "compaction")[-1].data["summary"]
    assert "src/config.py" in summary["changed_files"]
    assert any("edit_file" in fact for fact in summary["facts"])
    assert any("exit code: 7" in result for result in summary["validation"])


