def test_task_4_compaction_round_trips_through_the_disk_session_store(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    session.append("user_message", content="inspect files", kind="task")
    for number in range(6):
        _append_context_turn(session, number)
    manager = ContextManager(_encode_context_messages, policy=_context_policy())
    first = manager.prepare(session, "system")

    reloaded = store.load(session.session_id)
    before = reloaded.events
    replayed = manager.prepare(reloaded, "system")

    assert first.followed_compaction is True
    assert replayed.followed_compaction is False
    assert reloaded.events == before
    assert "Working summary:" in "\n".join(
        message["content"] for message in replayed.messages
    )


